1. //! Environment seed for the daemon: thin, documented constructors for the two
2. //! bindings so there is a single place to obtain a HAL handle and a STATE_DB
3. //! connection. The translation agents extend this into the real platform/DB layer
4. //! (per-port SFP handles, table helpers, publish/subscribe loops, …) as the
5. //! milestones grow — start here rather than calling the raw bindings ad hoc.
6. 
7. use platform_bridge::Platform;
8. use pyo3::prelude::*;
9. use pyo3::types::PyDict;
10. use swss_common::DbConnector;
11. 
12. /// STATE_DB hash the emulator's test-only SFP-error injection hook reads (mirrors
13. /// `sonic_platform.chassis.INJECT_TABLE`). Probed by [`init_embedded_db_config`] to prove the
14. /// embedded interpreter's STATE_DB read path (the emulator's `Chassis._get_statedb`) is warm.
15. const XCVR_EMU_INJECT: &str = "XCVR_EMU_INJECT";
16. 
17. /// SONiC STATE_DB logical index (Redis db number).
18. pub const STATE_DB: i32 = 6;
19. 
20. /// SONiC CONFIG_DB logical index (Redis db number).
21. pub const CONFIG_DB: i32 = 4;
22. 
23. /// SONiC APPL_DB logical index (Redis db number). Source of the `PORT_TABLE`
24. /// `flap_count` field the DOM task watches for link-change flag re-reads (M4).
25. pub const APPL_DB: i32 = 0;
26. 
27. /// Redis unix socket path inside pmon (override with the `REDIS_SOCK` env var).
28. pub fn redis_sock() -> String {
29.     std::env::var("REDIS_SOCK").unwrap_or_else(|_| "/var/run/redis/redis.sock".to_string())
30. }
31. 
32. /// Open the transceiver HAL: PyO3 → `sonic_platform.Platform().get_chassis()`.
33. ///
34. /// Constructing the platform triggers the emulator `List()` RPC (falls back to
35. /// `XCVR_EMU_NUM_SFPS` placeholders if the emulator isn't up yet — same as the
36. /// Python daemon at start-up). Hand the returned [`Platform`] out and call
37. /// `num_sfps()` / `sfp(i)` / `get_change_event(timeout_ms)`.
38. pub fn open_platform() -> platform_bridge::Result<Platform> {
39.     Platform::new()
40. }
41. 
42. /// Open a STATE_DB connection over the Redis unix socket.
43. ///
44. /// Use the returned [`DbConnector`] for direct hash access (`hset`/`hgetall`/…),
45. /// or wrap it in a `swss_common::Table` / `ProducerStateTable` for table-scoped
46. /// writes like `TRANSCEIVER_INFO`.
47. pub fn open_state_db() -> swss_common::Result<DbConnector> {
48.     DbConnector::new_unix(STATE_DB, redis_sock(), 0)
49. }
50. 
51. /// Open a CONFIG_DB connection over the Redis unix socket (for the PORT table /
52. /// logical↔physical port mapping).
53. pub fn open_config_db() -> swss_common::Result<DbConnector> {
54.     DbConnector::new_unix(CONFIG_DB, redis_sock(), 0)
55. }
56. 
57. /// Open an APPL_DB connection over the Redis unix socket (for the `PORT_TABLE`
58. /// `flap_count` link-change watch — M4). APPL_DB table keys are colon-separated
59. /// (`PORT_TABLE:Ethernet0`), so wrap this in a `RealDbTable::new_with_sep(_, ":")`.
60. pub fn open_appl_db() -> swss_common::Result<DbConnector> {
61.     DbConnector::new_unix(APPL_DB, redis_sock(), 0)
62. }
63. 
64. /// Force-load the embedded interpreter's process-global `swsscommon.SonicDBConfig` so the
65. /// emulator's `Chassis._get_statedb` (`SonicV2Connector(use_unix_socket_path=True)`) can
66. /// resolve STATE_DB's unix socket and surface injected SFP errors
67. /// (`tests/test_status_error.py`).
68. ///
69. /// WHY the daemon must do this (and the Python reference need not): the reference
70. /// `DaemonXcvrd` connects its DBs BY NAME at boot (`sonic_py_common.daemon_base.db_connect`,
71. /// `xcvrd.py:918` → `daemon_base.py:29`), which force-loads `SonicDBConfig` as a side effect
72. /// BEFORE the SFP task first polls `get_change_event`. The Rust daemon connects
73. /// STATE_DB/CONFIG_DB through the `swss-common` bindings by db-id + unix socket (see
74. /// [`open_state_db`]), which NEVER loads the Python singleton. So without this call nothing
75. /// loads `SonicDBConfig` in-process, and the emulator's FIRST `_get_statedb`
76. /// fail-caches `False` for the chassis lifetime — every injected SFP error then silently
77. /// returns `{}` and `TRANSCEIVER_STATUS_SW.error` is never written (gRPC presence events keep
78. /// working, which is why only the error-injection tests regress).
79. ///
80. /// We therefore reproduce the reference's by-name config-load side effect explicitly
81. /// (via [`load_embedded_sonic_db_config`]) at a clean single-threaded boot point, then VERIFY
82. /// the emulator's EXACT read path
83. /// (`SonicV2Connector(use_unix_socket_path=True).connect('STATE_DB').get_all(_, 'XCVR_EMU_INJECT')`)
84. /// so a `true` return means that identical later call inside `_get_statedb` cannot fail for
85. /// the `SonicDBConfig` reason. Bounded-retried (a just-restarted xcvrd can briefly race
86. /// redis/config readiness even though [`open_state_db`] already proved redis is up); every
87. /// distinct failure is logged. Best-effort and never fatal — a missing `swsscommon`/redis must
88. /// never take the daemon down; the caller primes the change-event baseline regardless.
89. pub fn init_embedded_db_config() -> bool {
90.     // Bounded retry budget for the cold-boot race where `redis` (the `database`
91.     // container) is not yet reachable the instant xcvrd starts inside `pmon`. The
92.     // reference daemon's by-name `db_connect(waitForDbInit=true)` (daemon_base) BLOCKS
93.     // until redis is up, so a too-short budget here is the one runtime way the
94.     // emulator's first `_get_statedb` fail-caches `False` for the chassis lifetime and
95.     // every injected SFP error is then silenced (tests/test_status_error.py). Mirror
96.     // the reference's resilience with a generous *bounded* budget instead of giving up
97.     // in ~6 s. When redis IS reachable (the steady/e2e case) attempt 1 succeeds
98.     // immediately, so this NEVER delays a healthy boot. Overridable (attempt count)
99.     // via `XCVRD_DBCFG_WARM_ATTEMPTS` for a Validator to tune without a rebuild.
100.     const DEFAULT_ATTEMPTS: usize = 100; // ~30 s at 300 ms/attempt
101.     let attempts = std::env::var("XCVRD_DBCFG_WARM_ATTEMPTS")
102.         .ok()
103.         .and_then(|v| v.parse::<usize>().ok())
104.         .filter(|n| *n > 0)
105.         .unwrap_or(DEFAULT_ATTEMPTS);
106.     let mut last_err: Option<String> = None;
107.     for attempt in 1..=attempts {
108.         let res = Python::with_gil(|py| -> PyResult<()> {
109.             // Same module the emulator imports: `from swsscommon.swsscommon import ...`.
110.             let sc = py.import_bound("swsscommon.swsscommon")?;
111.             // Best-effort: load the process-global `SonicDBConfig` singleton so by-name
112.             // resolution works. Swallowed inside; the probe below is the authority.
113.             load_embedded_sonic_db_config(&sc);
114.             // Authoritative go/no-go: reproduce the emulator's EXACT read path
115.             // (`chassis.py::_get_statedb` + `_read_injections`). If this succeeds here, the
116.             // emulator's own first call cannot fail-cache for the `SonicDBConfig` reason.
117.             let kwargs = PyDict::new_bound(py);
118.             kwargs.set_item("use_unix_socket_path", true)?;
119.             let conn = sc.getattr("SonicV2Connector")?.call((), Some(&kwargs))?;
120.             conn.call_method1("connect", ("STATE_DB",))?;
121.             conn.call_method1("get_all", ("STATE_DB", XCVR_EMU_INJECT))?;
122.             Ok(())
123.         });
124.         match res {
125.             Ok(()) => {
126.                 eprintln!(
127.                     "xcvrd-rs: embedded swsscommon SonicDBConfig loaded; STATE_DB reachable for \
128.                      the emulator SFP-error injection reader (attempt {attempt}/{attempts})"
129.                 );
130.                 return true;
131.             }
132.             Err(e) => {
133.                 // Log every DISTINCT failure (deduplicated) so a Validator e2e run reveals
134.                 // whether — and why — the emulator's STATE_DB read path is not warming (the
135.                 // sole runtime reason an injected SFP error would never surface).
136.                 let msg = e.to_string();
137.                 if last_err.as_deref() != Some(msg.as_str()) {
138.                     eprintln!(
139.                         "xcvrd-rs: init_embedded_db_config: STATE_DB read-path probe not yet warm \
140.                          (attempt {attempt}/{attempts}): {msg}"
141.                     );
142.                     last_err = Some(msg);
143.                     // First failure: dump a one-time env snapshot (is the default
144.                     // database_config.json where SonicDBConfig::initialize() looks?).
145.                     if attempt == 1 {
146.                         log_db_config_environment();
147.                     }
148.                 }
149.                 if attempt == attempts {
150.                     eprintln!(
151.                         "xcvrd-rs: init_embedded_db_config: could not prove the embedded STATE_DB \
152.                          read path warm after {attempts} attempts; priming the change-event \
153.                          baseline anyway (best-effort)"
154.                     );
155.                 } else {
156.                     std::thread::sleep(std::time::Duration::from_millis(300));
157.                 }
158.             }
159.         }
160.     }
161.     false
162. }
163. 
164. /// One-time diagnostic dumped on the first [`init_embedded_db_config`] failure: reports whether
165. /// the standard SONiC `database_config.json` is present at the default path the C++
166. /// `SonicDBConfig::initialize()` reads, plus the DB-path env the binary inherited — so a
167. /// config-load failure is diagnosable at a glance.
168. fn log_db_config_environment() {
169.     const DEFAULT_DB_CONFIG: &str = "/var/run/redis/sonic-db/database_config.json";
170.     let exists = std::path::Path::new(DEFAULT_DB_CONFIG).exists();
171.     let db_config_path = std::env::var("DB_CONFIG_PATH").unwrap_or_else(|_| "<unset>".into());
172.     let global_cfg = std::env::var("SONIC_DB_GLOBAL_CONFIG").unwrap_or_else(|_| "<unset>".into());
173.     eprintln!(
174.         "xcvrd-rs: init_embedded_db_config: db-config env snapshot — {DEFAULT_DB_CONFIG} \
175.          exists={exists}, DB_CONFIG_PATH={db_config_path}, SONIC_DB_GLOBAL_CONFIG={global_cfg}"
176.     );
177. }
178. 
179. /// Force-load the process-global `swsscommon.SonicDBConfig`. Every step is best-effort (errors
180. /// swallowed): the goal is that AT LEAST ONE strategy loads the singleton, and the caller's
181. /// `SonicV2Connector` probe is the authority on whether it worked. `sc` is `swsscommon.swsscommon`.
182. fn load_embedded_sonic_db_config(sc: &Bound<'_, PyModule>) {
183.     // Faithful to the reference `DaemonXcvrd.init()` (`xcvrd.py:1046-1048`): load the multi-ASIC
184.     // namespace map via `SonicDBConfig.initializeGlobalConfig()` ONLY when
185.     // `multi_asic.is_multi_asic()`. Calling it UNCONDITIONALLY on single-ASIC is NOT a harmless
186.     // no-op: with `SonicDBConfig` not yet initialized (the Rust `swss-common` bindings connect by
187.     // db-id + socket and never load the Python singleton), it flips the singleton into
188.     // global/namespace-resolution mode WITHOUT a `database_global.json`, so the emulator's later
189.     // `SonicV2Connector(...)` can no longer resolve STATE_DB and `_get_statedb` fail-caches. Gate
190.     // it exactly like the reference so single-ASIC takes the clean by-name lazy load below.
191.     let py = sc.py();
192.     let is_multi_asic = py
193.         .import_bound("sonic_py_common.multi_asic")
194.         .and_then(|m| m.call_method0("is_multi_asic")?.extract::<bool>())
195.         .unwrap_or(false);
196.     if is_multi_asic {
197.         if let Ok(cfg) = sc.getattr("SonicDBConfig") {
198.             let _ = cfg.call_method0("initializeGlobalConfig");
199.         }
200.     }
201.     // Reproduce the config-load SIDE EFFECT of the reference daemon's by-name `db_connect`
202.     // (`xcvrd.py:918` → `daemon_base.py:29`, `swsscommon.DBConnector("APPL_DB", 0, true)`):
203.     // resolving the db NAME force-loads `SonicDBConfig` from the local `database_config.json`
204.     // exactly as the reference does — the SAME lazy load the emulator's
205.     // `SonicV2Connector(use_unix_socket_path=True)` performs on its first `_get_statedb`. We pass
206.     // `waitForDbInit=false` (vs the reference's `true`) because we only need the load side effect,
207.     // not the connection, so it can never block the daemon at boot on a db not yet flagged
208.     // "initialized". Targets APPL_DB (as the reference does) and STATE_DB (what the emulator
209.     // reader actually uses) as independent fallbacks.
210.     if let Ok(dbc) = sc.getattr("DBConnector") {
211.         let _ = dbc.call1(("APPL_DB", 0i32, false));
212.         let _ = dbc.call1(("STATE_DB", 0i32, false));
213.     }
214. }
215. 
216. /// Decisive boot diagnostic for the emulator's SFP-error **delivery** path. The injected-error
217. /// tests (`tests/test_status_error.py`) surface a hardware error only when the emulator
218. /// `Chassis` reads the `XCVR_EMU_INJECT` STATE_DB hash, and that read has TWO independent
219. /// gates:
220. ///   1. the process-global `swsscommon.SonicDBConfig` resolves + STATE_DB is reachable, so the
221. ///      emulator's `_get_statedb` (`SonicV2Connector(use_unix_socket_path=True).connect(...)`)
222. ///      connects on its first call. Because the Rust `swss-common` bindings connect by db-id +
223. ///      socket and never load the Python singleton, [`init_embedded_db_config`] must load it
224. ///      first (mirroring the reference daemon's by-name `db_connect` side effect) — otherwise
225. ///      that first `_get_statedb` fail-caches `False` for the chassis lifetime and every
226. ///      injected error is silenced;
227. ///   2. the `.test_hooks` MARKER is present next to the `sonic_platform.chassis` module the
228. ///      embedded interpreter actually imported — the deploy drops it and the `Chassis`
229. ///      reads it ONCE at construction into `self._test_hooks`. If the marker is absent (or the
230. ///      interpreter imported `chassis.py` from a different path than the deploy patched),
231. ///      `_read_injections` short-circuits to `{}` with NO STATE_DB access at all — so an
232. ///      injected error can never surface even though gate 1 is green and live presence still
233. ///      works over gRPC.
234. /// This logs where `chassis.py` was imported from, the marker path it derives, whether that
235. /// marker exists, and whether `swsscommon` imports — so a Validator e2e run can tell a
236. /// config/redis failure (gate 1) apart from a marker/import-path failure (gate 2) at a glance.
237. /// Cheap: module-level attribute reads + one `os.path.exists`, no emulator RPC. Best-effort.
238. pub fn log_emulator_delivery_preconditions() {
239.     let _ = Python::with_gil(|py| -> PyResult<()> {
240.         let chassis_mod = py.import_bound("sonic_platform.chassis")?;
241.         let file: String = chassis_mod
242.             .getattr("__file__")
243.             .and_then(|f| f.extract())
244.             .unwrap_or_else(|_| "<unknown>".to_string());
245.         let marker: String = chassis_mod
246.             .getattr("TEST_HOOKS_MARKER")
247.             .and_then(|m| m.extract())
248.             .unwrap_or_else(|_| "<unknown>".to_string());
249.         let marker_exists = py
250.             .import_bound("os")
251.             .and_then(|os| os.getattr("path")?.call_method1("exists", (&marker,))?.extract())
252.             .unwrap_or(false);
253.         let swss_importable = py.import_bound("swsscommon.swsscommon").is_ok();
254.         eprintln!(
255.             "xcvrd-rs: emulator SFP-error delivery preconditions — sonic_platform.chassis={file}, \
256.              test_hooks_marker={marker}, marker_exists={marker_exists} (false => injected errors \
257.              are inert: no STATE_DB access, so tests/test_status_error.py cannot pass — the deploy \
258.              must drop .test_hooks next to THIS chassis.py), swsscommon_importable={swss_importable}"
259.         );
260.         Ok(())
261.     });
262. }
263.

