1. //! platform-bridge — typed Rust access to the Python `sonic_platform` plugin via PyO3.
2. //!
3. //! # Why this exists
4. //! The Rust rewrite of xcvrd must talk to the SAME transceiver plant the Python
5. //! daemon talks to: the `sonic_platform` plugin that speaks gRPC to `xcvr-emu`.
6. //! Its `Sfp` subclasses `SfpOptoeBase`, so the entire CMIS/SFF decode stack
7. //! (`get_transceiver_info`, `get_transceiver_dom_real_value`,
8. //! `get_transceiver_status`, lpmode/reset, …) already exists in Python, built on
9. //! three primitive hooks (`read_eeprom`/`write_eeprom`/`get_presence`).
10. //!
11. //! Rather than re-implement CMIS decode in Rust, we keep a THICK boundary: this
12. //! bridge embeds CPython, imports the real plugin, and exposes its high-level
13. //! results to Rust. The translation agents write only the daemon LOGIC on top of
14. //! this; they never reimplement the platform. Complex return values
15. //! (transceiver info/DOM/status dicts) are marshalled as `serde_json::Value` so
16. //! the surface stays stable as milestones add fields; scalars come back typed.
17. //!
18. //! # Runtime requirements
19. //! Embeds libpython3.13 (`auto-initialize`). At run time the process must find
20. //! `libpython3.13.so.1.0` and an importable `sonic_platform` — both true inside
21. //! pmon. Constructing [`Platform`] performs the emulator `List()` RPC, and the
22. //! `get_transceiver_*` calls perform EEPROM reads over gRPC, so `xcvr-emu` must
23. //! be running (it is, in pmon).
24. 
25. use std::collections::BTreeMap;
26. 
27. use pyo3::prelude::*;
28. use pyo3::types::{PyBytes, PyDict};
29. use serde_json::Value;
30. use thiserror::Error;
31. 
32. /// Errors surfaced by the bridge. Python failures include the formatted
33. /// traceback so import/attribute problems on the DUT are debuggable from logs.
34. #[derive(Error, Debug)]
35. pub enum BridgeError {
36.     #[error("python error: {0}")]
37.     Py(String),
38.     #[error("json marshalling error: {0}")]
39.     Json(String),
40.     #[error("bridge error: {0}")]
41.     Other(String),
42. }
43. 
44. impl From<PyErr> for BridgeError {
45.     fn from(e: PyErr) -> Self {
46.         Python::with_gil(|py| {
47.             let tb = e
48.                 .traceback_bound(py)
49.                 .and_then(|t| t.format().ok())
50.                 .unwrap_or_default();
51.             BridgeError::Py(format!("{e}\n{tb}"))
52.         })
53.     }
54. }
55. 
56. pub type Result<T> = std::result::Result<T, BridgeError>;
57. 
58. /// Crate version, for smoke logging.
59. pub fn bridge_version() -> &'static str {
60.     env!("CARGO_PKG_VERSION")
61. }
62. 
63. /// One transceiver change-event poll: `chassis.get_change_event(timeout)` returns
64. /// `(status, {'sfp': {port: code}, 'sfp_error': {port: code}})`. Keys are physical
65. /// port strings; values are xcvrd event codes (`"1"` insert, `"0"` remove, other =
66. /// SfpBase error bitmap).
67. #[derive(Debug, Clone, Default)]
68. pub struct ChangeEvent {
69.     pub status: bool,
70.     pub sfp: BTreeMap<String, String>,
71.     pub sfp_error: BTreeMap<String, String>,
72. }
73. 
74. /// `json.dumps(obj, default=str)` -> `serde_json::Value`. Robust to arbitrary
75. /// nesting and future fields; anything not natively JSON-able is str()'d.
76. fn py_to_json(py: Python<'_>, obj: &Bound<'_, PyAny>) -> Result<Value> {
77.     if obj.is_none() {
78.         return Ok(Value::Null);
79.     }
80.     let json = py.import_bound("json")?;
81.     let builtins = py.import_bound("builtins")?;
82.     let kwargs = PyDict::new_bound(py);
83.     kwargs.set_item("default", builtins.getattr("str")?)?;
84.     let dumped = json.call_method("dumps", (obj,), Some(&kwargs))?;
85.     let s: String = dumped.extract()?;
86.     serde_json::from_str(&s).map_err(|e| BridgeError::Json(e.to_string()))
87. }
88. 
89. /// Pull a `{str: str}` map out of a JSON object value (missing/!object -> empty).
90. fn json_str_map(v: Option<&Value>) -> BTreeMap<String, String> {
91.     let mut out = BTreeMap::new();
92.     if let Some(Value::Object(map)) = v {
93.         for (k, val) in map {
94.             let s = match val {
95.                 Value::String(s) => s.clone(),
96.                 other => other.to_string(),
97.             };
98.             out.insert(k.clone(), s);
99.         }
100.     }
101.     out
102. }
103. 
104. /// The transceiver plant: `sonic_platform.platform.Platform().get_chassis()`.
105. ///
106. /// Cheap to clone-free share across threads is NOT provided; construct once and
107. /// hand out [`Sfp`] handles. Each call re-acquires the GIL.
108. pub struct Platform {
109.     chassis: Py<PyAny>,
110. }
111. 
112. impl Platform {
113.     /// Import the plugin and build the chassis. Triggers the emulator `List()`
114.     /// RPC (falls back to `XCVR_EMU_NUM_SFPS` placeholders if the emulator is not
115.     /// up yet, exactly like the Python daemon at start-up).
116.     pub fn new() -> Result<Self> {
117.         Python::with_gil(|py| {
118.             let module = py.import_bound("sonic_platform.platform")?;
119.             let platform = module.getattr("Platform")?.call0()?;
120.             let chassis = platform.call_method0("get_chassis")?;
121.             Ok(Platform {
