1. //! STATE_DB seam (analysis 3.6) - the mockable boundary in front of the
2. //! `swss-common` Redis bindings.
3. //!
4. //! [`DbTable`] is a direct port of the `mock_swsscommon.Table` surface the Python
5. //! unit tests build (`set/get/hget/getKeys/_del/hdel/get_size/get_size_for_key`),
6. //! so Rust tests can assert **field counts** exactly as they do
7. //! (`dom_tbl.get_size_for_key("Ethernet0") == 27`). Production uses
8. //! [`RealDbTable`] (wraps a STATE_DB `DbConnector`); tests use
9. //! `crate::mock::MockDbTable`.
10. //!
11. //! Trait-semantics note (intentional, documented): the real swss `Table::set`
12. //! **merges** fields (an additive `HSET`, so a writer that only touches
13. //! `status`/`error` never clobbers the `cmis_state` another writer set), while the
14. //! Python `mock_swsscommon.Table.set` **replaces** the row (`mock_dict[key]=fvs`).
15. //! [`RealDbTable::set`] therefore merges and `MockDbTable::set` replaces, matching
16. //! each reference exactly. [`DbTable::hset`] merges a single field in both.
17. 
18. use std::collections::BTreeSet;
19. use std::sync::{Arc, Mutex, MutexGuard};
20. 
21. use swss_common::{CxxString, DbConnector};
22. 
23. use crate::error::Result;
24. 
25. /// A STATE_DB hash-of-hashes table keyed `TABLE|<logical_port>`. Interior
26. /// mutability (`&self` writers) matches the Python `Table` object.
27. pub trait DbTable: Send + Sync {
28.     /// `Table.set(key, FieldValuePairs)` - write a row (real: merge; mock: replace).
29.     fn set(&self, key: &str, fvs: &[(String, String)]);
30.     /// Merge a single field into a row (real `HSET`; used for the `cmis_state`
31.     /// projection so it never clobbers `status`/`error`).
32.     fn hset(&self, key: &str, field: &str, value: &str);
33.     /// `Table.get(key)` -> the row's field/value pairs, if present.
34.     fn get(&self, key: &str) -> Option<Vec<(String, String)>>;
35.     /// `Table.hget(key, field)` -> one field's value, if present.
36.     fn hget(&self, key: &str, field: &str) -> Option<String>;
37.     /// `Table._del(key)` - delete a whole row.
38.     fn del(&self, key: &str);
39.     /// `Table.hdel(key, field)` - delete one field (removing the row if empty).
40.     fn hdel(&self, key: &str, field: &str);
41.     /// `Table.getKeys()`.
42.     fn get_keys(&self) -> Vec<String>;
43.     /// `Table.get_size()` - number of rows.
44.     fn get_size(&self) -> usize;
45.     /// `Table.get_size_for_key(key)` - number of fields in a row.
46.     fn get_size_for_key(&self, key: &str) -> usize;
47. }
48. 
49. /// Real table: a named view over a shared STATE_DB [`DbConnector`].
50. ///
51. /// The daemon is the sole writer of `TRANSCEIVER_*`, so rows are addressed by the
52. /// explicit composite key `"<table>|<logical_port>"` (exactly what the M1 bootstrap
53. /// and the e2e harness read, e.g. `TRANSCEIVER_INFO|Ethernet0`) - no dependency on
54. /// `Table`'s separator handling. A local `keys` index tracks what we've written so
55. /// `get_keys`/`get_size` stay meaningful without a Redis `KEYS`/`SCAN`.
56. ///
57. /// `DbConnector` is `Send` but not `Sync`, so it is held behind an `Arc<Mutex<_>>`
58. /// (which is `Send + Sync`) to satisfy `DbTable: Send + Sync`; the two transceiver
59. /// tables share one connection.
60. pub struct RealDbTable {
61.     conn: Arc<Mutex<DbConnector>>,
62.     table_name: String,
63.     /// Redis key separator between the table name and the row key. STATE_DB /
64.     /// CONFIG_DB use `"|"` (the default); APPL_DB tables (e.g. `PORT_TABLE`) use
65.     /// `":"`. See [`RealDbTable::new_with_sep`].
66.     sep: String,
67.     keys: Mutex<BTreeSet<String>>,
68. }
69. 
70. impl RealDbTable {
71.     pub fn new(conn: Arc<Mutex<DbConnector>>, table_name: impl Into<String>) -> Self {
72.         Self::new_with_sep(conn, table_name, "|")
73.     }
74. 
75.     /// Build a table view whose Redis key is `"<table><sep><key>"`. Use `":"` for
76.     /// APPL_DB tables such as `PORT_TABLE` (`PORT_TABLE:Ethernet0`); STATE_DB and
77.     /// CONFIG_DB use the `"|"` default via [`RealDbTable::new`].
78.     pub fn new_with_sep(
79.         conn: Arc<Mutex<DbConnector>>,
80.         table_name: impl Into<String>,
81.         sep: impl Into<String>,
82.     ) -> Self {
83.         RealDbTable {
84.             conn,
85.             table_name: table_name.into(),
86.             sep: sep.into(),
87.             keys: Mutex::new(BTreeSet::new()),
88.         }
89.     }
90. 
91.     fn redis_key(&self, key: &str) -> String {
92.         format!("{}{}{}", self.table_name, self.sep, key)
93.     }
94. 
95.     fn track(&self, key: &str) {
96.         self.locked_keys().insert(key.to_string());
97.     }
98. 
99.     fn untrack(&self, key: &str) {
100.         self.locked_keys().remove(key);
101.     }
102. 
103.     /// Lock the shared STATE_DB connection, recovering from a poisoned mutex.
104.     ///
105.     /// The `DbConnector` is shared (`Arc<Mutex<_>>`) across the DOM/CMIS/SFP threads.
106.     /// If one thread panics while holding the lock (e.g. a PyO3 bridge error, or an
107.     /// `eprintln!` hitting a broken supervisor stderr pipe mid-write), a plain
108.     /// `.lock().unwrap()` on the other threads would panic too, cascading a single
109.     /// transient fault into a full `serve` teardown + chassis rebuild — which resets
110.     /// the emulator change-event baseline and drops in-flight SFP-error transitions.
111.     /// Python's GIL means one thread's exception never corrupts a shared object, so we
112.     /// mirror that: recover the guard and carry on. The connection is only read/written
113.     /// under this lock, so no partially-mutated invariant is exposed.
114.     fn locked_conn(&self) -> MutexGuard<'_, DbConnector> {
115.         self.conn.lock().unwrap_or_else(|e| e.into_inner())
116.     }
117. 
118.     /// Lock the per-table key set, recovering from a poisoned mutex (see
119.     /// [`Self::locked_conn`]).
120.     fn locked_keys(&self) -> MutexGuard<'_, BTreeSet<String>> {
121.         self.keys.lock().unwrap_or_else(|e| e.into_inner())
122.     }
123. }
124. 
125. impl DbTable for RealDbTable {
126.     fn set(&self, key: &str, fvs: &[(String, String)]) {
127.         let rkey = self.redis_key(key);
128.         let conn = self.locked_conn();
129.         for (field, value) in fvs {
130.             if let Err(e) = conn.hset(&rkey, field, &CxxString::new(value)) {
131.                 eprintln!("xcvrd-rs: hset {rkey}.{field} failed: {e}");
132.             }
133.         }
134.         drop(conn);
135.         self.track(key);
136.     }
137. 
138.     fn hset(&self, key: &str, field: &str, value: &str) {
139.         let rkey = self.redis_key(key);
140.         {
141.             let conn = self.locked_conn();
142.             if let Err(e) = conn.hset(&rkey, field, &CxxString::new(value)) {
143.                 eprintln!("xcvrd-rs: hset {rkey}.{field} failed: {e}");
144.             }
145.         }
146.         self.track(key);
147.     }
148. 
149.     fn get(&self, key: &str) -> Option<Vec<(String, String)>> {
150.         let rkey = self.redis_key(key);
151.         let conn = self.locked_conn();
152.         match conn.hgetall(&rkey) {
153.             Ok(map) if !map.is_empty() => Some(
154.                 map.into_iter()
155.                     .map(|(k, v)| (k, v.to_string_lossy().into_owned()))
156.                     .collect(),
157.             ),
158.             Ok(_) => None,
159.             Err(e) => {
160.                 eprintln!("xcvrd-rs: hgetall {rkey} failed: {e}");
161.                 None
162.             }
163.         }
164.     }
165. 
166.     fn hget(&self, key: &str, field: &str) -> Option<String> {
167.         let rkey = self.redis_key(key);
168.         let conn = self.locked_conn();
169.         match conn.hget(&rkey, field) {
170.             Ok(Some(v)) => Some(v.to_string_lossy().into_owned()),
171.             Ok(None) => None,
172.             Err(e) => {
173.                 eprintln!("xcvrd-rs: hget {rkey}.{field} failed: {e}");
174.                 None
175.             }
176.         }
177.     }
178. 
179.     fn del(&self, key: &str) {
180.         let rkey = self.redis_key(key);
181.         {
182.             let conn = self.locked_conn();
183.             if let Err(e) = conn.del(&rkey) {
184.                 eprintln!("xcvrd-rs: del {rkey} failed: {e}");
185.             }
186.         }
187.         self.untrack(key);
188.     }
189. 
190.     fn hdel(&self, key: &str, field: &str) {
191.         let rkey = self.redis_key(key);
192.         let conn = self.locked_conn();
193.         if let Err(e) = conn.hdel(&rkey, field) {
194.             eprintln!("xcvrd-rs: hdel {rkey}.{field} failed: {e}");
195.         }
196.         let empty = matches!(conn.hgetall(&rkey), Ok(map) if map.is_empty());
197.         drop(conn);
198.         if empty {
199.             self.untrack(key);
200.         }
201.     }
202. 
203.     fn get_keys(&self) -> Vec<String> {
204.         self.locked_keys().iter().cloned().collect()
205.     }
206. 
207.     fn get_size(&self) -> usize {
208.         self.locked_keys().len()
209.     }
210. 
211.     fn get_size_for_key(&self, key: &str) -> usize {
212.         let rkey = self.redis_key(key);
213.         let conn = self.locked_conn();
214.         conn.hgetall(&rkey).map(|m| m.len()).unwrap_or(0)
215.     }
216. }
217. 
218. /// Open a real STATE_DB-backed table over a shared connection.
219. pub fn open_state_table(conn: Arc<Mutex<DbConnector>>, name: &str) -> Result<RealDbTable> {
220.     Ok(RealDbTable::new(conn, name))
221. }
222.

