214. /// Real HAL: wraps `platform_bridge::Platform`, plus a daemon-owned side chassis for
215. /// the inf-safe DOM-threshold read (see [`ThrChassis`]).
216. pub struct BridgeHal {
217.     platform: platform_bridge::Platform,
218.     thr: Option<Arc<ThrChassis>>,
219. }
220. 
221. impl BridgeHal {
222.     /// Import the plugin + build the chassis (see `env::open_platform`).
223.     pub fn new() -> Result<Self> {
224.         Ok(Self::from_platform(platform_bridge::Platform::new()?))
225.     }
226. 
227.     /// Adopt an already-constructed bridge `Platform` and build the side chassis used
228.     /// for the inf-safe DOM-threshold read. If that side chassis can't be built, the
229.     /// daemon degrades to the bridge's (inf-fragile) threshold read — never worse than
230.     /// before — and logs once.
231.     pub fn from_platform(platform: platform_bridge::Platform) -> Self {
232.         let thr = match ThrChassis::new() {
233.             Ok(t) => Some(Arc::new(t)),
234.             Err(e) => {
235.                 eprintln!(
236.                     "xcvrd-rs: inf-safe DOM-threshold chassis unavailable ({e}); \
237.                      DOM_THRESHOLD for default zero/-inf modules may not publish"
238.                 );
239.                 None
240.             }
241.         };
242.         BridgeHal { platform, thr }
243.     }
244. }
245. 
246. impl Hal for BridgeHal {
247.     fn num_sfps(&self) -> Result<usize> {
248.         Ok(self.platform.num_sfps()?)
249.     }
250. 
251.     fn sfp(&self, index: usize) -> Result<Box<dyn SfpHandle>> {
252.         Ok(Box::new(BridgeSfp {
253.             sfp: self.platform.sfp(index)?,
254.             thr: self.thr.clone(),
255.             index,
256.         }))
257.     }
258. 
259.     fn get_change_event(&self, timeout_ms: u64) -> Result<ChangeEvent> {
260.         Ok(self.platform.get_change_event(timeout_ms)?)
261.     }
262. }
263. 
264. /// Real SFP handle: wraps `platform_bridge::Sfp` (thin delegation). Holds the
265. /// daemon-owned threshold chassis + physical index so the DOM-threshold read can go
266. /// through the inf-safe path (see [`ThrChassis`]); every other getter delegates to
267. /// the bridge unchanged.
268. pub struct BridgeSfp {
269.     sfp: platform_bridge::Sfp,
270.     thr: Option<Arc<ThrChassis>>,
271.     index: usize,
272. }
273. 
274. impl SfpHandle for BridgeSfp {
275.     fn get_presence(&self) -> Result<bool> {
276.         Ok(self.sfp.get_presence()?)
277.     }
278.     fn is_replaceable(&self) -> Result<bool> {
279.         Ok(self.sfp.is_replaceable()?)
280.     }
281.     fn get_reset_status(&self) -> Result<bool> {
282.         Ok(self.sfp.get_reset_status()?)
283.     }
284.     fn sfp_type(&self) -> Result<String> {
285.         Ok(self.sfp.sfp_type()?)
286.     }
287.     fn get_error_description(&self) -> Result<Option<String>> {
288.         Ok(self.sfp.get_error_description()?)
289.     }
290.     fn get_transceiver_info(&self) -> Result<Value> {
291.         Ok(self.sfp.get_transceiver_info()?)
292.     }
293.     fn get_transceiver_dom_real_value(&self) -> Result<Value> {
294.         Ok(self.sfp.get_transceiver_dom_real_value()?)
295.     }
296.     fn get_transceiver_status(&self) -> Result<Value> {
297.         Ok(self.sfp.get_transceiver_status()?)
298.     }
299.     fn get_transceiver_threshold_info(&self) -> Result<Value> {
300.         // Read via the daemon-owned chassis with non-finite sanitization so a default
301.         // module's `-inf` zero-power thresholds still publish TRANSCEIVER_DOM_THRESHOLD
302.         // (the thick bridge's serde_json marshal rejects the `-Infinity` token and
303.         // fails the whole read). Fall back to the bridge on any error, so this is never
304.         // worse than the bridge alone.
305.         if let Some(thr) = &self.thr {
306.             match thr.read_threshold_json(self.index) {
307.                 Ok(v) => return Ok(v),
308.                 Err(e) => {
309.                     eprintln!(
310.                         "xcvrd-rs: inf-safe DOM-threshold read (index {}) failed ({e}); \
311.                          falling back to bridge",
312.                         self.index
313.                     );
314.                 }
315.             }
316.         }
317.         Ok(self.sfp.get_transceiver_threshold_info()?)
318.     }
319.     fn get_lpmode(&self) -> Result<bool> {
320.         Ok(self.sfp.get_lpmode()?)
321.     }
322.     fn set_lpmode(&self, on: bool) -> Result<bool> {
323.         Ok(self.sfp.set_lpmode(on)?)
324.     }
325.     fn reset(&self) -> Result<bool> {
326.         Ok(self.sfp.reset()?)
327.     }
328.     fn call_json(&self, method: &str) -> Result<Value> {
329.         Ok(self.sfp.call_json(method, ())?)
330.     }
331.     fn read_eeprom(&self, offset: usize, num_bytes: usize) -> Result<Option<Vec<u8>>> {
332.         Ok(self.sfp.read_eeprom(offset, num_bytes)?)
333.     }
334.     fn write_eeprom(&self, offset: usize, data: &[u8]) -> Result<bool> {
335.         Ok(self.sfp.write_eeprom(offset, data)?)
336.     }
337. }
