30. /// get_size_for_key`, mirroring `mock_swsscommon.Table`.
31. pub struct MockDbTable {
32.     pub table_name: String,
33.     inner: Mutex<MockDbInner>,
34. }
35. 
36. impl MockDbTable {
37.     pub fn new(table_name: impl Into<String>) -> Self {
38.         MockDbTable {
39.             table_name: table_name.into(),
40.             inner: Mutex::new(MockDbInner {
41.                 keys: Vec::new(),
42.                 rows: HashMap::new(),
43.             }),
44.         }
45.     }
46. }
47. 
48. impl DbTable for MockDbTable {
49.     fn set(&self, key: &str, fvs: &[(String, String)]) {
50.         let mut g = self.inner.lock().unwrap();
51.         if !g.keys.iter().any(|k| k == key) {
52.             g.keys.push(key.to_string());
53.         }
54.         g.rows.insert(key.to_string(), fvs.to_vec());
55.     }
56. 
57.     fn hset(&self, key: &str, field: &str, value: &str) {
58.         let mut g = self.inner.lock().unwrap();
59.         if !g.keys.iter().any(|k| k == key) {
60.             g.keys.push(key.to_string());
61.         }
62.         let row = g.rows.entry(key.to_string()).or_default();
63.         if let Some(pair) = row.iter_mut().find(|(k, _)| k == field) {
64.             pair.1 = value.to_string();
65.         } else {
66.             row.push((field.to_string(), value.to_string()));
67.         }
68.     }
69. 
70.     fn get(&self, key: &str) -> Option<Vec<(String, String)>> {
71.         self.inner.lock().unwrap().rows.get(key).cloned()
72.     }
73. 
74.     fn hget(&self, key: &str, field: &str) -> Option<String> {
75.         let g = self.inner.lock().unwrap();
76.         g.rows
77.             .get(key)
78.             .and_then(|row| row.iter().find(|(k, _)| k == field).map(|(_, v)| v.clone()))
79.     }
80. 
81.     fn del(&self, key: &str) {
82.         let mut g = self.inner.lock().unwrap();
83.         if g.rows.remove(key).is_some() {
84.             g.keys.retain(|k| k != key);
85.         }
86.     }
87. 
88.     fn hdel(&self, key: &str, field: &str) {
89.         let mut g = self.inner.lock().unwrap();
90.         let empty = if let Some(row) = g.rows.get_mut(key) {
91.             row.retain(|(k, _)| k != field);
92.             row.is_empty()
93.         } else {
94.             return;
95.         };
96.         if empty {
